#!/usr/bin/env python3
import sys
import time


def main():
    for _ in sys.stdin:
        time.sleep(3600)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

def pick_actual_seed(seed: Optional[int]) -> int:
    if seed is None:
        return random.randint(1, 0xFFFFFFFF)
    wrapped = seed & 0xFFFFFFFF
    if wrapped == 0:
        return random.randint(1, 0xFFFFFFFF)
    return wrapped


def choose_default_dimensions(rng: random.Random, slot_count: int) -> Tuple[int, int]:
    if slot_count <= 1:
        size = rng.choice([20, 25, 30, 35, 40, 45, 50])
        return size, size
    if slot_count in (2, 4):
        size = rng.choice([20, 24, 28, 32, 36, 40, 44, 48])
        return size, size
    size = rng.choice([18, 24, 30, 36, 42, 48])
    return size, size


def adjust_dimensions(width: int, height: int, slot_count: int) -> Tuple[int, int]:
    if slot_count in (2, 4, 5, 6):
        width = max(2, width - (width % 2))
        height = max(2, height - (height % 2))
    if slot_count == 3:
        width = max(3, width - (width % 3))
        height = max(3, height - (height % 3))
    return width, height


def make_run_id() -> int:
    return int(time.time())


def cell_index(x: int, y: int, width: int) -> int:
    return y * width + x


def neighbors(x: int, y: int, width: int, height: int) -> Iterable[Tuple[int, int]]:
    yield ((x + 1) % width, y)
    yield ((x - 1) % width, y)
    yield (x, (y + 1) % height)
    yield (x, (y - 1) % height)


def reflect_horizontally(values: List[List[float]], width: int) -> List[List[float]]:
    out: List[List[float]] = []
    base_width = len(values[0])
    for row in values:
        reflected = row[:]
        while len(reflected) < width:
            mirrored = reflected[-2::-1] if width % 2 == 1 else reflected[::-1]
            for value in mirrored:
                if len(reflected) >= width:
                    break
                reflected.append(value)
        out.append(reflected[:width])
    return out


def reflect_quadrants(values: List[List[float]], width: int, height: int) -> List[List[float]]:
    horiz = reflect_horizontally(values, width)
    out = [row[:] for row in horiz]
    while len(out) < height:
        mirrored_rows = out[-2::-1] if height % 2 == 1 else out[::-1]
        for row in mirrored_rows:
            if len(out) >= height:
                break
            out.append(row[:])
    return out[:height]


def smooth_field(values: List[List[float]], passes: int) -> List[List[float]]:
    height = len(values)
    width = len(values[0])
    current = [row[:] for row in values]
    for _ in range(passes):
        nxt = [[0.0 for _ in range(width)] for _ in range(height)]
        for y in range(height):
            for x in range(width):
                total = current[y][x] * 4.0
                weight = 4.0
                for nx, ny in neighbors(x, y, width, height):
                    total += current[ny][nx] * 2.0
                    weight += 2.0
                for dx in (-1, 1):
                    for dy in (-1, 1):
                        total += current[(y + dy) % height][(x + dx) % width]
                        weight += 1.0
                nxt[y][x] = total / weight
        current = nxt
    return current


def symmetry_mode(slot_count: int) -> str:
    if slot_count in (2, 5, 6):
        return "horizontal"
    if slot_count in (3, 4):
        return "quadrant"
    return "none"


def expand_symmetric_field(rng: random.Random, width: int, height: int, slot_count: int, passes: int) -> List[List[float]]:
    mode = symmetry_mode(slot_count)
    if mode == "none":
        base_width = width
        base_height = height
    elif mode == "horizontal":
        base_width = max(1, (width + 1) // 2)
        base_height = height
    else:
        base_width = max(1, (width + 1) // 2)
        base_height = max(1, (height + 1) // 2)
    base = [[rng.random() for _ in range(base_width)] for _ in range(base_height)]
    base = smooth_field(base, passes)
    if mode == "none":
        return base
    if mode == "horizontal":
        return reflect_horizontally(base, width)
    return reflect_quadrants(base, width, height)


def starting_positions(width: int, height: int, slot_count: int) -> List[Tuple[int, int]]:
    cx = width // 2
    cy = height // 2
    if slot_count <= 1:
        return [(cx, cy)]
    if slot_count == 2:
        return [((cx - 1) % width, cy), (cx % width, cy)]
    if slot_count == 3:
        return [(width // 6, cy), ((width // 2) % width, cy), ((5 * width) // 6 % width, cy)]
    if slot_count == 4:
        return [
            ((cx - 1) % width, (cy - 1) % height),
            (cx % width, (cy - 1) % height),
            ((cx - 1) % width, cy % height),
            (cx % width, cy % height),
        ]
    if slot_count == 5:
        return [
            ((cx - 2) % width, cy),
            ((cx - 1) % width, cy),
            (cx % width, cy),
            ((cx + 1) % width, cy),
            ((cx + 2) % width, cy),
        ]
    return [
        ((cx - 2) % width, (cy - 1) % height),
        ((cx - 1) % width, (cy - 1) % height),
        (cx % width, (cy - 1) % height),
        ((cx - 2) % width, cy % height),
        ((cx - 1) % width, cy % height),
        (cx % width, cy % height),
    ]


def generate_map(
    width: int,
    height: int,
    slot_count: int,
    player_count: int,
    actual_seed: int,
) -> Tuple[List[int], List[int], List[int]]:
    rng = random.Random(actual_seed)
    production_field = expand_symmetric_field(rng, width, height, slot_count, 4)
    strength_field = expand_symmetric_field(rng, width, height, slot_count, 5)

    productions: List[int] = []
    strengths: List[int] = []
    for y in range(height):
        for x in range(width):
            p_value = int(round(production_field[y][x] * 14.0))
            s_value = int(round(20.0 + strength_field[y][x] * 230.0))
            productions.append(max(0, min(15, p_value)))
            strengths.append(max(0, min(255, s_value)))

    owners = [0 for _ in range(width * height)]
    starts = starting_positions(width, height, slot_count)
    for i, (x, y) in enumerate(starts[:slot_count]):
        idx = cell_index(x, y, width)
        strengths[idx] = max(40, min(120, strengths[idx]))
        if i < player_count:
            owners[idx] = i + 1
        else:
            owners[idx] = 0
    return productions, owners, strengths


def encode_state(owners: List[int], strengths: List[int]) -> str:
    rle: List[str] = []
    if owners:
        run_owner = owners[0]
        run_count = 1
        for owner in owners[1:]:
            if owner == run_owner:
                run_count += 1
                continue
            rle.append(str(run_count))
            rle.append(str(run_owner))
            run_owner = owner
            run_count = 1
        rle.append(str(run_count))
        rle.append(str(run_owner))
    return " ".join(rle + [str(value) for value in strengths]) + " \n"


def frame_grid(owners: List[int], strengths: List[int], width: int, height: int) -> List[List[List[int]]]:
    out: List[List[List[int]]] = []
    for y in range(height):
        row: List[List[int]] = []
        for x in range(width):
            idx = cell_index(x, y, width)
            row.append([owners[idx], strengths[idx]])
        out.append(row)
    return out


def blank_moves(width: int, height: int) -> List[List[int]]:
    return [[0 for _ in range(width)] for _ in range(height)]


def count_owned(owners: List[int], player_id: int) -> int:
    return sum(1 for owner in owners if owner == player_id)


def total_strength(owners: List[int], strengths: List[int], player_id: int) -> int:
    return sum(strength for owner, strength in zip(owners, strengths) if owner == player_id)


def parse_moves(line: str, owner_id: int, owners: List[int], width: int, height: int) -> Optional[List[List[int]]]:
    line = line.strip()
    grid = blank_moves(width, height)
    if not line:
        return grid
    parts = line.split()
    if len(parts) % 3 != 0:
        return None
    for i in range(0, len(parts), 3):
        try:
            x = int(parts[i], 10)
            y = int(parts[i + 1], 10)
            direction = int(parts[i + 2], 10)
        except ValueError:
            return None
        if direction not in DIR_DELTAS:
            return None
        if not (0 <= x < width and 0 <= y < height):
            continue
        idx = cell_index(x, y, width)
        if owners[idx] != owner_id:
            continue
        grid[y][x] = direction
    return grid


def pump_stdout(stream: Optional[Iterable[str]], sink: queue.Queue[Optional[str]]) -> None:
    if stream is None:
        sink.put(None)
        return
    try:
        for line in stream:
            sink.put(line)
    finally:
        sink.put(None)


def pump_stderr(stream: Optional[Iterable[str]], sink: List[str]) -> None:
    if stream is None:
        return
    for line in stream:
        sink.append(line.rstrip("\n"))


def launch_player(player: Player) -> None:
    process = subprocess.Popen(
        player.command,
        shell=True,
        executable="/bin/sh",
        stdin=subprocess.PIPE,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        bufsize=1,
    )
    player.process = process
    player.stdout_thread = threading.Thread(target=pump_stdout, args=(process.stdout, player.stdout_queue), daemon=True)
    player.stderr_thread = threading.Thread(target=pump_stderr, args=(process.stderr, player.stderr_lines), daemon=True)
    player.stdout_thread.start()
    player.stderr_thread.start()


def read_player_line(player: Player, timeout_seconds: Optional[float]) -> Optional[str]:
    if timeout_seconds is None:
        return player.stdout_queue.get()
    try:
        return player.stdout_queue.get(timeout=timeout_seconds)
    except queue.Empty:
        return "__TIMEOUT__"


def write_player(player: Player, text: str) -> None:
    if player.process is None or player.process.stdin is None:
        return
    try:
        player.process.stdin.write(text)
        player.process.stdin.flush()
    except BrokenPipeError:
        pass


def kill_player_process(player: Player) -> None:
    if player.process is None:
        return
    try:
        player.process.kill()
    except OSError:
        pass
    try:
        player.process.wait(timeout=0.2)
    except Exception:
        pass


def neutralize_player(owners: List[int], strengths: List[int], player_id: int) -> None:
    for i, owner in enumerate(owners):
        if owner != player_id:
            continue
        owners[i] = 0
        strengths[i] = 0


def resolve_turn(
    owners: List[int],
    strengths: List[int],
    productions: List[int],
    move_by_player: Dict[int, List[List[int]]],
    width: int,
    height: int,
) -> Tuple[List[int], List[int]]:
    provisional_owner = owners[:]
    had_layer = [False for _ in owners]
    layers: List[Dict[int, int]] = [dict() for _ in owners]

    for idx, owner in enumerate(owners):
        strength = strengths[idx]
        x = idx % width
        y = idx // width
        if owner == 0:
            if strength > 0:
                layers[idx][0] = strength
                had_layer[idx] = True
            continue
        move_grid = move_by_player.get(owner)
        direction = DIR_STILL
        if move_grid is not None:
            direction = move_grid[y][x]
        dx, dy = DIR_DELTAS[direction]
        tx = (x + dx) % width
        ty = (y + dy) % height
        tidx = cell_index(tx, ty, width)
        moving_strength = strength

        moving_strength = strength
        if direction == DIR_STILL:
            moving_strength = min(255, moving_strength + productions[idx])
        if moving_strength > 0:
            layers[tidx][owner] = min(255, layers[tidx].get(owner, 0) + moving_strength)
            had_layer[tidx] = True

    incoming_damage: List[Dict[int, int]] = [dict() for _ in owners]

    for idx, site_layers in enumerate(layers):
        if not site_layers:
            continue
        x = idx % width
        y = idx // width
        for owner, strength in site_layers.items():
            if strength <= 0:
                continue
            for other_owner in site_layers:
                if other_owner == owner:
                    continue
                incoming_damage[idx][other_owner] = incoming_damage[idx].get(other_owner, 0) + strength
            if owner == 0:
                continue
            for nx, ny in neighbors(x, y, width, height):
                nidx = cell_index(nx, ny, width)
                for other_owner, other_strength in layers[nidx].items():
                    if other_strength <= 0:
                        continue
                    if other_owner <= 0 or other_owner == owner:
                        continue
                    incoming_damage[nidx][other_owner] = incoming_damage[nidx].get(other_owner, 0) + strength

    next_owners = provisional_owner[:]
    next_strengths = [0 for _ in owners]
    for idx, site_layers in enumerate(layers):
        remaining: Dict[int, int] = {}
        for owner, strength in site_layers.items():
            damage = incoming_damage[idx].get(owner, 0)
            left = strength - damage
            if left > 0:
                remaining[owner] = left
        if remaining:
            positive_players = [(owner, strength) for owner, strength in remaining.items() if owner > 0]
            if positive_players:
                positive_players.sort(key=lambda item: (item[1], item[0]), reverse=True)
                next_owners[idx] = positive_players[0][0]
                next_strengths[idx] = min(255, positive_players[0][1])
                continue
            next_owners[idx] = 0
            next_strengths[idx] = remaining.get(0, 0)
            continue
        if had_layer[idx]:
            next_owners[idx] = 0
            next_strengths[idx] = 0
            continue
        next_strengths[idx] = 0
    return next_owners, next_strengths


def make_log_path(player_id: int, run_id: int, cwd: Path) -> Path:
    return cwd / f"{player_id}-{run_id}.log"


def write_player_log(player: Player, run_id: int, cwd: Path, phase: str) -> None:
    if not player.stderr_lines and not player.error_message:
        return
    path = make_log_path(player.player_id, run_id, cwd)
    lines = [f" --- {phase} ---", ""]
    if player.error_message:
        lines.append("ERRORED!")
        lines.append(player.error_message)
    if player.stderr_lines:
        if lines[-1] != "":
            lines.append("")
        lines.extend(player.stderr_lines)
    path.write_text("\n".join(lines).rstrip("\n") + "\n", encoding="utf-8")
    player.log_path = path


def format_path_for_output(path: Path, default_to_dot: bool = False) -> str:
    if path.is_absolute():
        return str(path)
    text = str(path)
    if default_to_dot and not text.startswith("./"):
        return f"./{text}"
    return text


def rank_players(players: List[Player], owners: List[int], strengths: List[int]) -> None:
    scored = []
    for player in players:
        scored.append(
            (
                count_owned(owners, player.player_id),
                total_strength(owners, strengths, player.player_id),
                player.player_id,
                player,
            )
        )
    scored.sort(key=lambda item: (item[0], item[1], item[2]), reverse=True)
    for rank, (_, _, _, player) in enumerate(scored, start=1):
        player.rank = rank


def quiet_footer(players: List[Player]) -> None:
    errored = [player for player in players if player.log_path is not None]
    if not errored:
        write_stdout(" \n")
        return
    for player in errored:
        write_stdout(f"{player.player_id} \n")
        write_stdout(f"{player.log_path.name} \n")


def replay_data(
    frames: List[List[List[List[int]]]],
    moves: List[List[List[int]]],
    productions: List[int],
    width: int,
    height: int,
    players: List[Player],
) -> Dict[str, object]:
    return {
        "frames": frames,
        "height": height,
        "moves": moves,
        "num_frames": len(frames),
        "num_players": len(players),
        "player_names": [player.name for player in players],
        "productions": [productions[y * width : (y + 1) * width] for y in range(height)],
        "version": 11,
        "width": width,
    }


def main(argv: List[str]) -> int:
    try:
        cfg = parse_args(argv)
    except ParseFailure as exc:
        print_parse_error(exc.argument, exc.message)
        return 1

    if cfg.show_help:
        print_help()
        return 0
    if cfg.show_version:
        print_version()
        return 0
    if not cfg.bot_args:
        write_stdout(GENERIC_NO_BOT)
        return 1
    if cfg.override_names and (len(cfg.bot_args) < 2 or len(cfg.bot_args) % 2 != 0):
        write_stdout(INVALID_OVERRIDE)
        return 1

    if cfg.override_names:
        commands = cfg.bot_args[::2]
        override_names = cfg.bot_args[1::2]
    else:
        commands = cfg.bot_args[:]
        override_names = [None for _ in commands]

    if cfg.nplayers is not None and commands and not (1 <= cfg.nplayers <= 6):
        for command in commands:
            write_stdout(f"{command}\n")
            if not cfg.quiet:
                write_stdout(f"{command}\n")
        write_stdout(INVALID_PLAYER_COUNT)
        return 1

    actual_seed = pick_actual_seed(cfg.seed)
    rng = random.Random(actual_seed)
    player_count = len(commands)
    slot_count = cfg.nplayers if player_count == 1 and cfg.nplayers is not None else max(player_count, cfg.nplayers or 0)
    if slot_count <= 0:
        slot_count = player_count

    if cfg.dimensions is not None:
        req_width, req_height = cfg.dimensions
    else:
        req_width, req_height = choose_default_dimensions(rng, slot_count)
    if req_width <= 0 or req_height <= 0:
        for command in commands:
            write_stdout(f"{command}\n")
        os.kill(os.getpid(), signal.SIGSEGV)
        return 139
    width, height = adjust_dimensions(req_width, req_height, slot_count)

    replay_dir = cfg.replay_dir or Path(".")
    if not cfg.noreplay and not replay_dir.exists():
        write_stderr(REPLAY_DIR_ERROR)
        return 134

    if not cfg.override_names:
        for command in commands:
            write_stdout(f"{command}\n")
            if not cfg.quiet:
                write_stdout(f"{command}\n")
    write_stdout(f"{width} {height}\n")

    productions, owners, strengths = generate_map(width, height, slot_count, player_count, actual_seed)
    single_player_mode = player_count == 1

    players = [
        Player(player_id=i + 1, command=command, override_name=override_names[i])
        for i, command in enumerate(commands)
    ]

    init_timeout = None if cfg.ignore_timeouts else 5.0
    turn_timeout = None if cfg.ignore_timeouts else 2.0
    cwd = Path.cwd()

    for player in players:
        launch_player(player)
        if not cfg.quiet:
            write_stdout(f"Init Message sent to player {player.player_id}.\n")
        write_player(player, f"{player.player_id}\n")
        write_player(player, f"{width} {height} \n")
        write_player(player, " ".join(str(value) for value in productions) + " \n")
        write_player(player, encode_state(owners, strengths))

    for player in players:
        response = read_player_line(player, init_timeout)
        if response == "__TIMEOUT__" or response is None:
            player.init_failed = True
            player.alive = False
            if player.override_name is not None:
                player.name = player.override_name
            elif player.stderr_lines:
                player.name = player.stderr_lines[0]
            else:
                player.name = f"Bot #{player.player_id}; timed out during Init"
            player.error_message = "No response received."
            if single_player_mode:
                player.single_player_init_failure = True
                player.alive = True
                player.last_alive_frame = 0
            else:
                player.init_failed_before_frame0 = True
                neutralize_player(owners, strengths, player.player_id)
                player.last_alive_frame = -1
            write_player_log(player, make_run_id(), cwd, "Init")
            continue
        received_name = response.rstrip("\n").strip()
        if player.override_name is not None:
            player.name = player.override_name
        else:
            player.name = received_name
        if not cfg.quiet:
            write_stdout(f"Init Message received from player {player.player_id}, {player.name}.\n")

    run_id = make_run_id()
    if any(player.log_path is not None for player in players):
        for player in players:
            if player.log_path is None and player.error_message:
                write_player_log(player, run_id, cwd, "Init")
    for player in players:
        if player.log_path is None and player.error_message:
            write_player_log(player, run_id, cwd, "Init")

    frames = [frame_grid(owners, strengths, width, height)]
    moves_history: List[List[List[int]]] = []
    max_turns = int(math.floor(10.0 * math.sqrt(width * height)))

    current_owners = owners[:]
    current_strengths = strengths[:]
    frame_index = 0

    for turn_number in range(max_turns):
        if not cfg.quiet:
            write_stdout(f"Turn {turn_number + 1}\n")

        if single_player_mode and players[0].single_player_init_failure:
            neutralize_player(current_owners, current_strengths, players[0].player_id)
            players[0].alive = False
            players[0].single_player_init_failure = False
            move_by_player = {players[0].player_id: blank_moves(width, height)}
            moves_history.append(blank_moves(width, height))
            frames.append(frame_grid(current_owners, current_strengths, width, height))
            frame_index += 1
            continue

        state_line = encode_state(current_owners, current_strengths)
        for player in players:
            if not player.alive:
                continue
            write_player(player, state_line)

        move_by_player: Dict[int, List[List[int]]] = {}
        aggregate_move_grid = blank_moves(width, height)
        for player in players:
            if not player.alive:
                continue
            response = read_player_line(player, turn_timeout)
            if response == "__TIMEOUT__" or response is None:
                player.alive = False
                player.error_message = "No response received."
                write_player_log(player, run_id, cwd, "Turn")
                neutralize_player(current_owners, current_strengths, player.player_id)
                continue
            parsed = parse_moves(response, player.player_id, current_owners, width, height)
            if parsed is None:
                player.alive = False
                player.error_message = "Failed to parse moves."
                write_player_log(player, run_id, cwd, "Turn")
                neutralize_player(current_owners, current_strengths, player.player_id)
                continue
            move_by_player[player.player_id] = parsed
            for y in range(height):
                for x in range(width):
                    if parsed[y][x] != 0:
                        aggregate_move_grid[y][x] = parsed[y][x]

        next_owners, next_strengths = resolve_turn(
            current_owners,
            current_strengths,
            productions,
            move_by_player,
            width,
            height,
        )

        moves_history.append(aggregate_move_grid)
        current_owners = next_owners
        current_strengths = next_strengths
        frames.append(frame_grid(current_owners, current_strengths, width, height))
        frame_index += 1

        alive_players: List[Player] = []
        for player in players:
            if player.init_failed_before_frame0:
                continue
            owned_now = count_owned(current_owners, player.player_id)
            if owned_now > 0:
                player.alive = True
                alive_players.append(player)
            else:
                if player.alive and player.last_alive_frame < 0:
                    player.last_alive_frame = frame_index - 1
                player.alive = False

        if single_player_mode:
            if count_owned(current_owners, players[0].player_id) == width * height:
                break
            continue
        if len(alive_players) <= 1:
            break

    final_frame_index = len(frames) - 1
    for player in players:
        if player.init_failed_before_frame0:
